package com.labmaker.app;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;import java.nio.charset.StandardCharsets;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
public class AcademicCacheTest {
 static final String A="12345678901",B="99999999999";
 static class Files implements AcademicCache.Store {Map<String,String> values=new HashMap<>();boolean fail=false;public String read(String name){return values.get(name);}public void write(String name,String value)throws Exception{if(fail)throw new java.io.IOException("fixture failure");values.put(name,value);}public void remove(String name){values.remove(name);}}
 static class Keys implements AcademicCache.Keys {SecretKey key;Keys()throws Exception{KeyGenerator generator=KeyGenerator.getInstance("AES");generator.init(256);key=generator.generateKey();}public SecretKey get(boolean create){return key;}}
 static final AcademicCache.Codec CODEC=new AcademicCache.Codec(){public String encode(byte[] value){return Base64.getEncoder().encodeToString(value);}public byte[] decode(String value){return Base64.getDecoder().decode(value);}};
 AcademicTimetable.Snapshot snapshot(String account)throws Exception{return AcademicTimetable.normalize(new JSONObject().put("account",account).put("semester","2026-2027-1").put("calendar",new JSONObject().put("XQKSRQ","2026-09-07")).put("courses",new JSONArray().put(new JSONObject().put("KCM","模拟课程").put("KCH","M").put("SKZC","111").put("SKXQ","4").put("KSJC","7").put("JSJC","8"))).put("changes",new JSONArray()).put("notArranged",new JSONArray()),account,100000);}
 @Test public void encryptedRestartRecoveryPreservesExactDataAndNeverRestoresFresh()throws Exception{
  Files files=new Files();Keys keys=new Keys();AcademicCache cache=new AcademicCache(files,keys,CODEC);AcademicTimetable.Snapshot original=snapshot(A);cache.save(original);String disk=files.values.get(AcademicCache.name(A));assertFalse(disk.contains(A));assertFalse(disk.contains("模拟课程"));assertFalse(AcademicCache.name(A).contains(A));AcademicTimetable.Snapshot restored=new AcademicCache(files,keys,CODEC).load(A);assertEquals(original.json().toString(),restored.json().toString());assertEquals("unknown",AcademicTimetable.conflict(restored,A,"实验",new AcademicTimetable.Interval(java.time.LocalDate.of(2026,9,18),java.time.LocalTime.of(19,0),java.time.LocalTime.of(21,25)),"晚上",List.of(),false).status);
 }
 @Test public void copyingCiphertextAcrossAccountsAndTamperingAreRejectedWithoutErasingOtherRecords()throws Exception{
  Files files=new Files();Keys keys=new Keys();AcademicCache cache=new AcademicCache(files,keys,CODEC);cache.save(snapshot(A));String old=files.values.get(AcademicCache.name(A));files.values.put(AcademicCache.name(B),old);assertThrows(Exception.class,()->cache.load(B));assertNotNull(cache.load(A));JSONObject tampered=new JSONObject(old);byte[] bytes=CODEC.decode(tampered.getString("ciphertext"));bytes[0]^=1;tampered.put("ciphertext",CODEC.encode(bytes));files.values.put(AcademicCache.name(A),tampered.toString());assertThrows(Exception.class,()->cache.load(A));assertEquals(2,files.values.size());
 }
 @Test public void partialAndFailedSavesKeepLastCompleteCacheAndRepeatedWritesUseNewIv()throws Exception{
  Files files=new Files();Keys keys=new Keys();AcademicCache cache=new AcademicCache(files,keys,CODEC);cache.save(snapshot(A));String first=files.values.get(AcademicCache.name(A));files.fail=true;assertThrows(Exception.class,()->cache.save(snapshot(A)));assertEquals(first,files.values.get(AcademicCache.name(A)));files.fail=false;
  AcademicTimetable.Snapshot original=snapshot(A),partial=new AcademicTimetable.Snapshot(A,original.semester,original.start,original.end,original.events,List.of("未完整读取"),List.of(),false,200000);assertThrows(Exception.class,()->cache.save(partial));assertEquals(first,files.values.get(AcademicCache.name(A)));cache.save(original);assertNotEquals(first,files.values.get(AcademicCache.name(A)));
 }
 @Test public void lostKeyAndMalformedFileNeedExplicitAccountClear()throws Exception{
  Files files=new Files();Keys keys=new Keys();AcademicCache cache=new AcademicCache(files,keys,CODEC);cache.save(snapshot(A));cache.save(snapshot(B));assertThrows(Exception.class,()->new AcademicCache(files,new Keys(),CODEC).load(A));files.values.put(AcademicCache.name(A),"broken");assertThrows(Exception.class,()->cache.load(A));cache.clear(A);assertNull(cache.load(A));assertNotNull(cache.load(B));cache.clear(A);assertNotNull(cache.load(B));assertThrows(Exception.class,()->AcademicCache.name("../bad"));
 }
 @Test public void authenticatedButMalformedSnapshotStillCannotBeUsed()throws Exception{
  Files files=new Files();Keys keys=new Keys();AcademicCache cache=new AcademicCache(files,keys,CODEC);JSONObject value=snapshot(A).json();value.getJSONArray("events").getJSONObject(0).put("end","10:00");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,keys.key);cipher.updateAAD(("lab-academic-cache:v1:"+A).getBytes(StandardCharsets.UTF_8));files.values.put(AcademicCache.name(A),new JSONObject().put("version",1).put("iv",CODEC.encode(cipher.getIV())).put("ciphertext",CODEC.encode(cipher.doFinal(value.toString().getBytes(StandardCharsets.UTF_8)))).toString());assertThrows(Exception.class,()->cache.load(A));
 }
}
